    }

    @Override
    @Transactional
    public void savePet(Pet pet) throws DataAccessException {
        pet.setType(findPetTypeById(pet.getType().getId()));
        petRepository.save(pet);
    }

    @Override
    @Transactional
    public void saveVisit(Visit visit) throws DataAccessException {
        visitRepository.save(visit);

    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Vet> findVets() throws DataAccessException {
        return vetRepository.findAll();
    }

    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        if (owner.isNew()) {
            owner.setCustomerCode(customerCode(owner.getLastName(), ownerRepository.count() + 1));
            owner.setNamesakeCount((int) ownerRepository.countByFirstNameAndLastNameIgnoringCase(
                lowerCase(owner.getFirstName()), lowerCase(owner.getLastName())));
        }
        ownerRepository.save(owner);

    }

    @Override
    @Transactional(readOnly = true)
    public boolean ownerTelephoneExists(String telephone) throws DataAccessException {
        return ownerRepository.existsByTelephone(telephone);
    }

    @Override
    @Transactional(readOnly = true)
    public boolean ownerHouseholdExists(String lastName, String address) throws DataAccessException {
        return !findHouseholdMembers(lastName, address).isEmpty();
    }

    @Override
    @Transactional
    public void joinHousehold(Owner owner) throws DataAccessException {
        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
        if (members.isEmpty()) {
            return;
        }
        String householdId = members.stream()
            .map(Owner::getHouseholdId)
            .filter(id -> id != null && !id.isBlank())
            .findFirst()
            .orElseGet(() -> UUID.randomUUID().toString());
        for (Owner member : members) {
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
        owner.setHouseholdId(householdId);
    }

    /**
     * Finds the owners with the same last name (ignoring case and runs of whitespace) and the same
     * normalized address.
     */
    private List<Owner> findHouseholdMembers(String lastName, String address) {
        String normalizedAddress = AddressNormalizer.normalize(address);
        return ownerRepository.findByLastNameIgnoringCase(normalizeForComparison(lastName)).stream()
            .filter(existing -> AddressNormalizer.normalize(existing.getAddress()).equals(normalizedAddress))
            .toList();
    }

    /** Trims the value, collapses runs of whitespace into a single space and lower-cases it. */
    private static String normalizeForComparison(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String lowerCase(String value) {
        return value == null ? null : value.toLowerCase(Locale.ROOT);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    /**
     * Builds a customer code '&lt;LAST3&gt;-&lt;NNNN&gt;': the upper-cased first three letters of the
     * last name followed by the zero-padded sequence number.
     */
    private static String customerCode(String lastName, long sequence) {
        String letters = lastName == null ? "" : lastName.codePoints()
            .filter(Character::isLetter)
            .limit(3)
            .collect(StringBuilder::new, StringBuilder::appendCodePoint, StringBuilder::append)
            .toString();
        return String.format("%s-%04d", letters.toUpperCase(Locale.ROOT), sequence);
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

}

